/// orig 1000:0000 (380 bytes). Ghidra parameter order. The C main() of ULTIMA.EXE (Ghidra never created a function here; crt0 at 1000:017e pushes envp/argv/argc and `CALL 0`, then passes the return value to exit(02f4)). (1) Option letter: c = argc>1 ? to_upper(argv[1][0]) : ' '; sets the video-selection flags g_force_cga=(c=='C'), g_flag_herc=(c=='H'), 
pub fn main_entry(gm: &mut Game, argc: i16, argv: i16) {
    // (1) option letter: argv is not available in the port; the letter comes from U5_VIDEO
    // (C/E/T/H, default E) instead of argv[1][0].
    let _ = (argc, argv);
    let mut opt: i8 = b' ' as i8; // local_6
    let env = std::env::var("U5_VIDEO").unwrap_or_else(|_| "E".to_string());
    if let Some(&c) = env.as_bytes().first() {
        opt = util::to_upper(c as i16) as i8;
    }
    gm.set_g16(g::FORCE_CGA, (opt == b'C' as i8) as u16);
    gm.set_g16(g::FLAG_HERC, (opt == b'H' as i8) as u16);
    gm.set_g16(g::FLAG_TANDY, (opt == b'T' as i8) as u16);
    gm.set_g16(g::FLAG_EGA, (opt == b'E' as i8) as u16);
    // (2) disk state
    gm.set_g16(g::ERROR_HOOK, 0x2322); // disk_error_hook
    gm.set_g16(g::ERROR_HOOK_SEG, 0x1000);
    gm.set_g8(g::CUR_DISK, 0);
    gm.set_g8(g::DISPLAY_MODE, 0);
    gm.set_g8(g::FLOPPY_COUNT, 1);
    let drive = files::get_current_drive_letter(gm);
    gm.set_g8(g::DISK_DRIVE_LETTERS, drive);
    let letter: u8 = if drive < 0x43 { 0xff } else { drive }; // [bp-6]
    gm.set_g8(g::DISK1_DRIVE_LETTER, letter);
    gm.set_g8(g::DISK3_DRIVE_LETTER, 0xff);
    gm.set_g16(g::OOL_BUFFER_PTR, 0xb21e);
    gm.set_g16(g::FLUSH_AFTER_KEY, 1);
    gm.set_g8(0xa9ca, letter); // DAT_1f64_a9ca: g_disk_drive_letters[2]
    gm.set_g8(0xa9cd, letter); // DAT_1f64_a9cd: g_disk_drive_letters[5]
    // (3) the whole title/intro; returns only when a game is to be played
    ovl::intro::run_intro(gm);
    // (4)
    draw_status_window(gm);
    // (5) the location loop ([bp-8] = from_dungeon, [bp-2] = quit; see listing 1000:00b3-0176)
    let mut from_dungeon: i16 = 0;
    loop {
        let mut quit: i16 = 0;
        if gm.g8(g::LOCATION) == 0 {
            ovl::mainout::run_overworld(gm);
            quit = 1;
            from_dungeon = 0;
        }
        if gm.g8(g::LOCATION) != 0 {
            if gm.g8(g::LOCATION) < 0x21 {
                let arrived: i16 = if quit != 0 || from_dungeon != 0 { 1 } else { 0 };
                ovl::town::enter_town(gm, arrived);
                ovl::town::town_main_loop(gm);
                from_dungeon = 0;
            } else {
                files::select_disk(gm, 2);
                ovl::dungeon::dungeon_main(gm, quit as u16);
                from_dungeon = 1;
            }
            quit = 0;
            files::select_disk(gm, 1);
            loop {
                if files::file_exists(gm, g::STR_BRIT_DAT2) != 0 { break; }
            }
            let name = ovl::outsubs::ool_file_name(gm);
            files::load_file_region(gm, 0, 0x100, g::MONSTER_TABLE, name);
            if gm.g8(g::LOCATION) == 0 && gm.g8(g::PARTY_Z) != 0 {
                files::select_disk(gm, 5);
                loop {
                    if files::file_exists(gm, g::STR_UNDER_DAT) != 0 { break; }
                }
                let name = ovl::outsubs::ool_file_name(gm);
                files::save_file_region(gm, 0x100, g::MONSTER_TABLE, name);
            }
        }
        // LAB_1000_016e
        if quit != 0 { break; }
    }
    // (6)
    gfx::restore_video_mode(gm);
}

