/// orig 1000:6794 (108 bytes). Ghidra parameter order. For a party-side roster entry (flags & 0x80) that is neither inactive nor asleep (flags & 0x28 == 0): if the member's ring (record +0x1d) is item 42 '*' (Invisibility Ring) the combatant's monster-table anim tile (slot +1) becomes 0x1d (sprite 0x11d, the invisible marker) and roster flag 0x10 (invis
pub fn apply_ring_effects(gm: &mut Game, roster_index: i16) {
    let off = (roster_index as u16).wrapping_mul(8);
    let flags = gm.g8(g::ROSTER_FLAGS.wrapping_add(off));
    if (flags & 0x80) != 0 && (flags & 0x28) == 0 {
        let member = gm.g8(g::ROSTER_MEMBER.wrapping_add(off)) as u16;
        let ring = gm.g8(g::PARTY_RING.wrapping_add(member.wrapping_mul(0x20)));
        if ring == b'*' {
            let slot = gm.g8(g::ROSTER_SLOT.wrapping_add(off)) as u16;
            gm.set_g8(g::PARTY_VEHICLE_TILE.wrapping_add(slot.wrapping_mul(8)), 0x1d);
            gm.set_g8(g::ROSTER_FLAGS.wrapping_add(off), flags | 0x10);
        } else if ring == b',' {
            // the pushed member index is ignored by regeneration_ring_tick (no parameters)
            regeneration_ring_tick(gm);
        }
    }
}

/// orig 1000:6800 (127 bytes). Ghidra parameter order. Clears the asleep/incapacitated state (roster flag 8) of a combatant: for a monster the monster-table anim state (slot +6) is zeroed (animation resumes); for a party member the status becomes 'G' and the anim tile is restored to the base tile (slot +0), or to 0x1d if the invisible flag 0x10 is set. 
pub fn wake_combatant(gm: &mut Game, roster_index: i16) {
    let off = (roster_index as u16).wrapping_mul(8);
    let flags = gm.g8(g::ROSTER_FLAGS.wrapping_add(off));
    if (flags & 8) != 0 {
        let slot = gm.g8(g::ROSTER_SLOT.wrapping_add(off)) as u16;
        if (flags & 0x80) == 0 {
            gm.set_g8(g::MONSTER_ANIM_STATE.wrapping_add(slot.wrapping_mul(8)), 0);
        } else {
            let member = gm.g8(g::ROSTER_MEMBER.wrapping_add(off)) as u16;
            gm.set_g8(g::PARTY_STATUS.wrapping_add(member.wrapping_mul(0x20)), 0x47); // 'G'
            if (flags & 0x10) == 0 {
                let so = slot.wrapping_mul(8);
                let base = gm.g8(g::MONSTER_TABLE.wrapping_add(so));
                gm.set_g8(g::PARTY_VEHICLE_TILE.wrapping_add(so), base);
            } else {
                gm.set_g8(g::PARTY_VEHICLE_TILE.wrapping_add(slot.wrapping_mul(8)), 0x1d);
            }
        }
        let f = gm.g8(g::ROSTER_FLAGS.wrapping_add(off)) & 0xf7;
        gm.set_g8(g::ROSTER_FLAGS.wrapping_add(off), f);
    }
    draw_status_window(gm);
}

/// orig 1000:6880 (46 bytes). Ghidra parameter order. Calls incapacitate_combatant(index) unless the entry is a party member whose status is 'P' (poisoned members cannot fall asleep). Used by CMDS_bf80 when camping to put everyone except the watch to sleep.
pub fn sleep_combatant_unless_poisoned(gm: &mut Game, roster_index: i16) {
    let off = (roster_index as u16).wrapping_mul(8);
    let flags = gm.g8(g::ROSTER_FLAGS.wrapping_add(off));
    let member = gm.g8(g::ROSTER_MEMBER.wrapping_add(off)) as u16;
    if (flags & 0x80) == 0 || gm.g8(g::PARTY_STATUS.wrapping_add(member.wrapping_mul(0x20))) != b'P' {
        incapacitate_combatant(gm, roster_index as u16);
    }
}

/// orig 1000:68ae (135 bytes). Ghidra parameter order. Puts a combatant to sleep. Monster: roster flag 8 set, g_combat_state_flags = 4, monster-table anim state (slot +6) = 0xff (frozen). Party member: return if dead; status = 'S', flag 8 set, anim tile = 0x1e (sprite 0x11e, sleeping body); if this was g_active_member it becomes 0xff; g_combat_state_fla
pub fn incapacitate_combatant(gm: &mut Game, roster_index: u16) {
    let off = roster_index.wrapping_mul(8); // iVar1
    let flags = gm.g8(g::ROSTER_FLAGS.wrapping_add(off));
    let slot = gm.g8(g::ROSTER_SLOT.wrapping_add(off)) as u16;
    if (flags & 0x80) == 0 {
        gm.set_g8(g::ROSTER_FLAGS.wrapping_add(off), flags | 8);
        gm.set_g8(g::COMBAT_STATE_FLAGS, 4);
        gm.set_g8(g::MONSTER_ANIM_STATE.wrapping_add(slot.wrapping_mul(8)), 0xff);
    } else {
        let member = gm.g8(g::ROSTER_MEMBER.wrapping_add(off)) as u16;
        let status_p = g::PARTY_STATUS.wrapping_add(member.wrapping_mul(0x20));
        if gm.g8(status_p) == b'D' {
            return;
        }
        gm.set_g8(status_p, b'S');
        gm.set_g8(g::ROSTER_FLAGS.wrapping_add(off), flags | 8);
        gm.set_g8(g::PARTY_VEHICLE_TILE.wrapping_add(slot.wrapping_mul(8)), 0x1e);
        if roster_index == gm.g8(g::ACTIVE_MEMBER) as u16 {
            gm.set_g8(g::ACTIVE_MEMBER, 0xff);
        }
        gm.set_g8(g::COMBAT_STATE_FLAGS, 4);
        draw_status_window(gm);
        if (gm.g8(g::COMBAT_FLAGS) & 4) != 0 {
            return;
        }
    }
    refresh_map_view(gm);
}

