    let (y1, y2) = if y1 <= y2 { (y1, y2) } else { (y2, y1) };
    let (x1, x2) = (x1.clamp(0, 319), x2.clamp(0, 319));
    let (y1, y2) = (y1.clamp(0, 199), y2.clamp(0, 199));
